import json
d=json.load(open('/home/user_aioc/.config/opencode/opencode.json'))
print('=== TOP KEYS ===')
for k in d.keys(): print(' ',k)
print()
print('=== MCP servers ===')
mcp=d.get('mcp',{})
if isinstance(mcp,dict):
    for name,cfg in mcp.items():
        if isinstance(cfg,dict):
            print(f'- {name}: {cfg.get(\"command\",\"?\")} {cfg.get(\"args\",[])}')
"

